/* From Uiverse.io by ElektroRaks - Tags: card, polygon, blur filter, text animation, rotate, clip-path */
.__UIV_SCOPE__ .card {
  width: 11.875em;
  height: 15.875em;
  background: linear-gradient(135deg, #1afbf0, #da00ff);
  background-position: center;
  background-size: cover;
  background-repeat: no-repeat;
}

.__UIV_SCOPE__ .box {
  width: 100%;
  height: 100%;
  background-color: rgba(255, 255, 255, 0.074);
  -webkit-backdrop-filter: blur(20px);
  backdrop-filter: blur(20px);
}

.__UIV_SCOPE__ .content {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  width: 100%;
  height: 100%;
  padding: 10px;
  background-position: center;
  background-size: cover;
  background-repeat: no-repeat;
  clip-path: polygon(54% 27%, 100% 50%, 100% 100%, 51% 74%, 0 50%, 0% 0%);
  transition: 0.5s;
  line-height: 1.2;
}

.__UIV_SCOPE__ .card-title {
  width: 100%;
  font-weight: bold;
  color: white;
  display: block;
  padding-top: 6.3em;
  font-size: 1.2em;
  transform: rotate(34deg);
  transition: 0.5s;
  margin-left: 25%;
}

.__UIV_SCOPE__ .text {
  color: white;
  opacity: 0;
  transition: 0.5s;
}

.__UIV_SCOPE__ .card:hover .content {
  clip-path: polygon(100% 0, 100% 50%, 100% 100%, 0% 100%, 0 50%, 0% 0%);
}

.__UIV_SCOPE__ .card:hover .card-title {
  padding-top: 1em;
  margin-left: 0%;
  transform: rotate(0deg);
}

.__UIV_SCOPE__ .card:hover .text {
  opacity: 1;
}
